const text = (value) => typeof value === 'string' || typeof value === 'number' ? String(value).trim() : '';
const instanceId = text($json.instance_id);
const workflowId = text($json.workflow?.id);
if (!instanceId || instanceId === 'YOUR_INSTANCE_ID') throw new Error('Configure a unique instance identity in Flashduty settings');
if (instanceId.length > 64) throw new Error('Instance identity length must not exceed 64 characters');
if (!workflowId) throw new Error('Missing failed workflow identity');
const severity = $json.severity;
if (!['Critical', 'Warning', 'Info'].includes(severity)) throw new Error('Invalid severity: use Critical, Warning, or Info');
const isTriggerFailure = !!$json.trigger && !$json.execution;
const executionId = isTriggerFailure ? text($execution.id) : text($json.execution?.id);
if (!executionId) throw new Error('Missing execution identity; enable saving failed executions');
const failureType = isTriggerFailure ? 'trigger' : 'execution';
const alertKey = JSON.stringify(['n8n', instanceId, workflowId, failureType, executionId]);
if (alertKey.length > 255) throw new Error('Alert identity is too long');
const error = isTriggerFailure ? $json.trigger.error : $json.execution.error;
const workflowName = text($json.workflow?.name) || workflowId;
const nodeName = text($json.execution?.lastNodeExecuted);
// Keep the execution link, but exclude query strings, fragments, and URL credentials.
const sourceUrl = text($json.execution?.url).match(/^https?:\/\/[^\s?#]+/)?.[0] || '';
const safeUrl = /^https?:\/\/[^/]*@/.test(sourceUrl) ? '' : sourceUrl;
const lines = [
  `Workflow: ${workflowName.slice(0, 256)} (${workflowId})`,
  `Failure: ${failureType}; execution: ${executionId}`,
  nodeName ? `Node: ${nodeName.slice(0, 128)}` : '',
  safeUrl ? `Execution: ${safeUrl.slice(0, 512)}` : '',
  text(error?.message).slice(0, 1000),
].filter(Boolean);
return { json: {
  title: `n8n workflow failed: ${workflowName}`.slice(0, 512),
  event_status: severity,
  alert_key: alertKey,
  description: lines.join('\n').slice(0, 2048),
  labels: { integration: 'n8n', instance_id: instanceId, workflow_id: workflowId,
    failure_type: failureType, execution_id: executionId },
} };

if ($json.error) throw new Error('Flashduty rejected the alert; inspect its response and request_id');
if (typeof $json.request_id !== 'string' || !$json.request_id || typeof $json.data?.alert_key !== 'string' || !$json.data.alert_key) {
  throw new Error('Flashduty did not return an alert confirmation; check the push URL and response');
}
return { json: { request_id: $json.request_id, alert_key: $json.data.alert_key } };
